export const DedicationCard: Component<DedicationCardProps> = (props: DedicationCardProps) => {
	const [isHover, setIsHover] = createSignal(false);

	const onHover = () => {
		setIsHover(true);
		if (props.onHover) {
			props.onHover();
		}
	};

	const onDehover = () => {
		setIsHover(false);
		if (props.onDehover) {
			props.onDehover();
		}
	};

	const dndContext = useDragAndDropContext();

	const isDragging = createMemo(() => {
		const draggable = dndContext.isDragging();
		if (draggable != null && draggable.data == props.id) {
			return true;
		}

		return false;
	});

	return (
		<div class={`flex ${props.class ? props.class : ""}`}>
			<Draggable
				disabled={props.isDisplayOnly || props.disabled}
				data={props.id}
				onDragStart={props.onDragStart}
				onDragEnd={props.onDragEnd}
				onDragDrop={props.onDragDrop}
				canDrop={props.canDrop}
				ghostElementStyle={{
					opacity: "0.3",
				}}
			>
				<Activatable
					class={`flex flex-auto justify-center relative`}
					onActivate={props.isDisplayOnly || props.disabled ? undefined : props.onDedicationActivate}
					onFocus={props.isDisplayOnly || props.disabled ? undefined : onHover}
					onBlur={props.isDisplayOnly || props.disabled ? undefined : onDehover}
					id={props.id}
					style={{
						// MouseEnter in drag and drop doesn't work if the pointer events consume the input
						"pointer-events": `${isDragging() ? "none" : "auto"}`,
						cursor: `${props.isDisplayOnly ? "auto" : "pointer"}`,
						opacity: props.disabled ? "0.3" : "1",
					}}
					disableFocus={props.isDisplayOnly}
					name="DedicationCard"
					tabIndex={props.tabIndex}
					autoFocus={props.tabIndex == 0}
				>
					<DedicationCardContents
						{...props}
						isHover={isHover}
						isDragging={isDragging}
						onHover={onHover}
						onDehover={onDehover}
					/>
				</Activatable>
			</Draggable>
		</div>
	);
};

interface EmptySlotProps extends JSX.HTMLAttributes<HTMLDivElement> {
	onHover?: () => void;
}

export const EmptySlot = (props: EmptySlotProps) => {
	const [isHover, setIsHover] = createSignal(false);

	const onHover = () => {
		setIsHover(true);
		if (props.onHover) {
			props.onHover();
		}
	};

	const onDehover = () => {
		setIsHover(false);
	};

	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();

	return (
		<Activatable
			class={`${isMobile ? "flex" : ""} flex-auto justify-center ${props.class}`}
			onFocus={onHover}
			onBlur={onDehover}
			tabIndex={props.tabIndex}
			autoFocus={props.tabIndex == 0}
		>
			<MetalCardFrame
				onMouseEnter={onHover}
				onMouseLeave={onDehover}
				class={`${isMobile && isSmallScreen() ? "w-96 min-h-36" : "w-72 h-32"} max-w-full flex flex-auto justify-center items-center font-fit-shrink text-xs relative`}
				style={{
					filter: "grayscale(1)",
					width: isMobile && !isSmallScreen() ? `${Layout.pixelsToScreenPixels(412)}px` : undefined,
					"min-height": isMobile && !isSmallScreen() ? `${Layout.pixelsToScreenPixels(182)}px` : undefined,
				}}
			>
				<div
					class="absolute inset-0 metal-card-frame-bg-hover"
					style={{
						filter: "grayscale(1)",
					}}
					classList={{
						invisible: !isHover(),
					}}
				/>
				<div
					class="absolute inset-0 py-2 px-3 flex flex-col items-center justify-center uppercase"
					classList={{
						"text-secondary-1": isHover(),
						"text-secondary-2": !isHover(),
					}}
					style={{
						"background-image":
							"radial-gradient(140% 120% at top, rgba(172, 8, 142, 0.4), rgba(172, 8, 142, 0.35) 10%, rgba(172, 8, 142,0) 35%)",
					}}
				>
					<L10n.Stylize text={"LOC_DEDICATIONS_EMPTY_SLOT"} />
				</div>
			</MetalCardFrame>
		</Activatable>
	);
};

const DedicationSelectionComponent = () => {
	let overlay!: HTMLDivElement;

	const model = DedicationsModel.get();
	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();
	const audio = useAudio("ChooseDedicationsPopup");
	const dedicationAudio = useAudio("ChooseDedicationsPopup/DragonDrop/DedicationCard");

	const hotkeyContext = useContext(HotkeyContext);

	const [shouldAutoFocusEmpty, setShouldAutoFocusEmpty] = createSignal(true);
	const [shouldAutoFocusAvailable, setShouldAutoFocusAvailable] = createSignal(false);

	onMount(() => {
		hotkeyContext.registerNavtray("cancel", "LOC_GENERIC_BACK");
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("cancel");
	});

	const onCardUpdated = () => {
		model.updateSelectedItems();
	};

	const onEffectUsed = () => {
		model.applyEffects();
	};

	const buttonConfirm: ButtonProps = {
		onActivate: () => {
			const isSlotsFull = model.state.selectedItems.length == model.DEDICATIONS_SLOT_IDS.length;
			DialogManager.createDialog_ConfirmCancel({
				title: "LOC_DEDICATIONS_CONFIRM_DEDICATIONS_TITLE",
				body: isSlotsFull
					? "LOC_DEDICATIONS_CONFIRM_DEDICATIONS_FULL"
					: "LOC_DEDICATIONS_CONFIRM_DEDICATIONS_EMPTY",
				canClose: false,
				displayQueue: "SystemMessage",
				addToFront: true,
				callback: (eAction: DialogBoxAction) => {
					if (eAction == DialogBoxAction.Confirm) {
						model.confirmDeck();
						ContextManager.pop("screen-dedication-selection");
					} else {
						setTimeout(() => {
							// TODO: replace with inputContext definition (in component) when SolidJS components supports them.
							Input.setActiveContext(InputContext.Shell);
						}, 300);
					}
				},
			});
		},
		name: "LOC_GENERIC_CONFIRM",
	};
	const buttonViewMap: ButtonProps = {
		onActivate: () => {
			ContextManager.pop("screen-dedication-selection");
		},
		name: "LOC_ADVANCED_START_VIEW_MAP",
	};

	onMount(() => {
		audio("popup-open");
		Telemetry.sendCardSelectionStart();
		engine.on("AdvancedStartCardAdded", onCardUpdated);
		engine.on("AdvancedStartCardRemoved", onCardUpdated);
		engine.on("AdvancedStartEffectUsed", onEffectUsed);
	});

	onCleanup(() => {
		engine.off("AdvancedStartCardAdded", onCardUpdated);
		engine.off("AdvancedStartCardRemoved", onCardUpdated);
		engine.off("AdvancedStartEffectUsed", onEffectUsed);
	});

	const handleDragDrop: DragDropCallback = (draggable, dropzone) => {
		const dragged = draggable.data as string;
		if (!model.hasItem(dropzone.data as string)) {
			model.equipItem(dragged, dropzone.data as string);
		} else {
			model.swapItem(dragged, dropzone.data as string);
		}
		dedicationAudio("dropAccept", { cardType: draggable.data as string });
	};

	const canEquipItem: DragDropPredicate = (draggable, dropzone) => {
		const memo = createMemo(() => {
			const item = typeof draggable.data == "string" ? draggable.data : "";
			const slot = typeof dropzone.data == "string" ? dropzone.data : "";

			return item != "" && slot != "" ? model.canContain(slot) : false;
		});
		return memo;
	};

	const handleEquipmentDragEnd: DragEndCallback = (draggable, status, _zone, _position) => {
		switch (status) {
			case DragEndStatus.Released:
				dedicationAudio("dropReleased");
				model.unEquipItem(draggable.data as string);
				break;
			case DragEndStatus.RejectedByDropzone:
				dedicationAudio("dropReject");
				break;
		}
	};

	const handleActivateDedication = (card: DedicationCardItem) => {
		// It's currently in the available container, equip into the first available Slot(1|2|3|...)
		if (model.contains(card.id, model.DEDICATIONS_AVAILABLE_ID) && model.canAutoSlotItem(card.id)) {
			model.autoSlotItem(card.id);
			setShouldAutoFocusEmpty(false);
			setShouldAutoFocusAvailable(true);
			return;
		}

		// It's currently in a Slot(1|2|3|...), so unequip the item.
		if (model.DEDICATIONS_SLOT_IDS.some((slot) => model.contains(card.id, slot))) {
			model.unEquipItem(card.id);
			setShouldAutoFocusEmpty(true);
			setShouldAutoFocusAvailable(false);
		}
	};

	const getNavTrayText = (id: string) => {
		if (model.contains(id, model.DEDICATIONS_AVAILABLE_ID)) {
			return "LOC_GENERIC_SELECT";
		}

		return "LOC_GENERIC_REMOVE";
	};

	return (
		<Panel
			name="Dedication Selection Screen"
			id="screen-dedication-selection"
			class={`${isMobile ? "fullscreen" : "flex"}`}
			style={
				isMobile
					? {}
					: {
							height: model.isSmallScreen() ? "auto" : Layout.pixels(860),
							width: model.isSmallScreen() ? "auto" : Layout.pixels(1060),
							position: model.isSmallScreen() ? "absolute" : undefined,
							top: model.isSmallScreen() ? Layout.pixels(-10) : "auto",
							bottom: model.isSmallScreen() ? Layout.pixels(-10) : "auto",
							left: model.isSmallScreen() ? Layout.pixels(-18) : "auto",
							right: model.isSmallScreen() ? Layout.pixels(-18) : "auto",
						}
			}
		>
			<div
				class="absolute z-1"
				ref={overlay}
			/>
			<AudioContextProvider segment="ChooseDedicationsPopup">
				<OrnatePopupFrame
					class="flex-auto"
					style={{
						"padding-bottom": isMobile
							? Layout.pixels(8)
							: model.isSmallScreen()
								? Layout.pixels(0)
								: Layout.pixels(12),
					}}
					topIconSrc={model.isSmallScreen() ? "" : "url('blp:sub_legacy_color')"}
					topIconClass="size-9 -mt-1"
					topIconBackgroundTint={"#0089ff"}
					longFiligree={!isMobile}
					noClose={!isMobile}
					closePopupCallback={isMobile ? () => ContextManager.pop("screen-dedication-selection") : undefined}
					isFullscreen={isMobile}
				>
					<div
						class={`absolute top-0 ${isMobile ? "left-2 mt-2" : "left-6 mt-4"} bottom-0 h-1/2 w-64 img-frame-filigree pointer-events-none`}
					/>
					<div
						class={`absolute top-0 ${isMobile ? "right-2 mt-2" : "right-6 mt-4"} bottom-0 h-1/2 w-64 rotate-y-180 img-frame-filigree pointer-events-none`}
					/>

					<Show
						when={!model.isSmallScreen()}
						fallback={
							<div class={`${isMobile ? "relative mt-6" : ""}`}>
								<Filigree.TitleAccent>
									<OrnateTopIcon
										class="mr-2"
										style={{
											height: Layout.pixels(36),
											width: Layout.pixels(36),
										}}
										iconClass="size-5 -mt-0"
										backgroundTint={"#0089ff"}
										iconSrc={"url('blp:sub_legacy_color')"}
									/>
									<Header class={`flex-auto max-w-full text-center justify-center`}>
										<L10n.Compose text="LOC_DEDICATIONS_CHOOSE_DEDICATIONS" />
									</Header>
								</Filigree.TitleAccent>
							</div>
						}
					>
						<div class="max-w-full relative mt-4 mb-2">
							<FiligreeTitle.H2
								text={"LOC_DEDICATIONS_CHOOSE_DEDICATIONS"}
								bgGlow
							/>
						</div>
					</Show>
					<VSlot
						class="flex-auto w-full items-center"
						autoFocus={true}
					>
						<AudioContextProvider segment="DragonDrop">
							<DragAndDrop
								onDragDrop={handleDragDrop}
								debugTrace={false}
								overlayParent={overlay}
							>
								<HSlot
									class="justify-center"
									tabindex={0}
									autoFocus={shouldAutoFocusEmpty()}
								>
									<For each={model.DEDICATIONS_SLOT_IDS}>
										{(slot: string, index) => (
											<Dropzone
												debugId={`Empty Dropzone ${slot}`}
												data={slot}
												canDrop={canEquipItem}
											>
												<Show
													when={model.items(slot)[0]}
													keyed
													fallback={
														<EmptySlot
															class={`${isMobile ? `my-2 ${isSmallScreen() ? "mx-4" : "mx-7"}` : "m-2"}`}
															onHover={() => hotkeyContext.unregisterNavtray("accept")}
															tabIndex={index()}
														/>
													}
												>
													{(slotCard) => (
														<DedicationCard
															id={slotCard.id}
															class="flex-auto"
															contentClass={`${isMobile ? `my-4 ${isSmallScreen() ? "mx-4" : "mx-7"}` : "m-3"}`}
															title={slotCard.title}
															description={slotCard.description}
															background={slotCard.descriptionBG}
															icon={slotCard.traitIcon}
															onDragEnd={handleEquipmentDragEnd}
															onDedicationActivate={() =>
																handleActivateDedication(slotCard)
															}
															onHover={() =>
																hotkeyContext.registerNavtray(
																	"accept",
																	getNavTrayText(model.items(slot)[0].id),
																)
															}
															onDehover={() => hotkeyContext.unregisterNavtray("accept")}
															tabIndex={index()}
														/>
													)}
												</Show>
											</Dropzone>
										)}
									</For>
								</HSlot>
								<div
									class={`flex flex-col items-center pointer-events-none ${isMobile ? "relative" : ""}`}
									style={{
										"margin-top": model.isSmallScreen() ? Layout.pixels(4) : Layout.pixels(12),
										"margin-bottom": model.isSmallScreen() ? Layout.pixels(4) : Layout.pixels(12),
									}}
									role="heading"
								>
									<Header class={`max-w-full text-center justify-center}`}>
										<L10n.Compose text={"LOC_DEDICATIONS_AVAILABLE_DEDICATIONS"} />
									</Header>
									<div class="flex items-center font-body text-accent-2 text-sm mt-1">
										<L10n.Compose text={"LOC_DEDICATIONS_CHOOSE_DEDICATIONS_DESC"} />
									</div>
								</div>
								<div class={`flex flex-auto ${isMobile ? "px-5" : ""}`}>
									<InnerFrame class="flex-auto w-full">
										<ScrollArea
											class={`flex-auto ${isMobile ? "px-5 py-2" : ""}`}
											useProxy
											reserveSpace
										>
											<Dropzone
												debugId="Dedication Available Dropzone"
												data={model.DEDICATIONS_AVAILABLE_ID}
												canDrop={canEquipItem}
											>
												<SpatialSlot
													name="Available Spatial Slot"
													class="flex justify-center items-start flex-wrap relative left-3 p-3"
													tabIndex={1}
													autoFocus={shouldAutoFocusAvailable()}
												>
													<For each={model.items(model.DEDICATIONS_AVAILABLE_ID)}>
														{(card, index) => (
															<DedicationCard
																id={card.id}
																contentClass={`${isMobile ? `my-4 ${isSmallScreen() ? "mx-4" : "mx-7"}` : "m-3"} mt-5`}
																title={card.title}
																description={card.description}
																background={card.descriptionBG}
																icon={card.traitIcon}
																disabled={card.isDisabled}
																onDragEnd={handleEquipmentDragEnd}
																onDedicationActivate={() =>
																	handleActivateDedication(card)
																}
																onHover={() =>
																	hotkeyContext.registerNavtray(
																		"accept",
																		getNavTrayText(card.id),
																	)
																}
																onDehover={() =>
																	hotkeyContext.unregisterNavtray("accept")
																}
																tabIndex={index()}
															/>
														)}
													</For>
												</SpatialSlot>
											</Dropzone>
										</ScrollArea>
									</InnerFrame>
								</div>
							</DragAndDrop>
						</AudioContextProvider>
						<HSlot
							class={`my-5 justify-center items-center ${isMobile ? "relative" : ""}`}
							tabIndex={2}
						>
							<Header role="heading">
								<L10n.Compose text={"LOC_DEDICATIONS_PICK_YOUR_CAPITAL"} />
							</Header>
							<Dropdown
								class="ml-2 w-96 pointer-events-auto"
								defaultValue={model.getSelectedCapitalCity()}
								onItemSelected={(item) => model.setSelectedCapital(item!.id)}
								selectedItemTemplate={(item) => (
									<span class="m-1 truncate">
										{item!.isCapital ? (
											<L10n.Compose
												text={"LOC_DEDICATIONS_CURRENT_CAPITAL"}
												args={[item!.name]}
											/>
										) : (
											<L10n.Compose text={item!.name} />
										)}
									</span>
								)}
							>
								<For each={model.getAllCapitals()}>
									{(item) => (
										<DropdownItem value={item}>
											{item!.isCapital ? (
												<L10n.Compose
													text={"LOC_DEDICATIONS_CURRENT_CAPITAL"}
													args={[item!.name]}
												/>
											) : (
												<L10n.Compose text={item!.name} />
											)}
										</DropdownItem>
									)}
								</For>
							</Dropdown>
						</HSlot>
						<HSlot
							style={{
								"margin-bottom": isMobile
									? Layout.pixels(18)
									: model.isSmallScreen()
										? Layout.pixels(56)
										: Layout.pixels(24),
							}}
							tabIndex={3}
						>
							<AudioContextProvider segment="Confirm">
								<Button
									class="mx-3"
									onActivate={buttonConfirm.onActivate}
								>
									<L10n.Compose text={buttonConfirm.name || ""} />
								</Button>
							</AudioContextProvider>
							<AudioContextProvider segment="ViewMap">
								<Button
									class="mx-3"
									onActivate={buttonViewMap.onActivate}
								>
									<L10n.Compose text={buttonViewMap.name || ""} />
								</Button>
							</AudioContextProvider>
						</HSlot>
					</VSlot>
				</OrnatePopupFrame>
			</AudioContextProvider>
		</Panel>
	);
};

export const DedicationSelection = ComponentRegistry.register({
	name: "DedicationSelection",
	createInstance: DedicationSelectionComponent,
});

defineLegacyComponent(
	"screen-dedication-selection",
	{ classNames: ["fullscreen", "flex", "justify-center", "items-center"] },
	() => {
		Input.setActiveContext(InputContext.Shell);
		return <DedicationSelection />;
	},
);
